{
  "name": "opencode-local-provider",
  "version": "0.1.8",
  "type": "module",
  "license": "MIT",
  "description": "OpenCode plugin that adds a 'local' provider with auto-detection for Ollama, LMStudio, llama.cpp, vLLM, Exo, llama-swap, oMLX, and MLX-VLM",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/goniz/opencode-local-provider.git"
  },
  "module": "./dist/index.js",
  "main": "./dist/index.js",
  "exports": {
    ".": "./dist/index.js",
    "./server": "./dist/index.js"
  },
  "files": [
    "dist",
    "README.md"
  ],
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "opencode",
    "plugin",
    "llm",
    "ollama",
    "lmstudio",
    "llama.cpp",
    "vllm",
    "exo",
    "omlx",
    "mlx-vlm",
    "local"
  ],
  "scripts": {
    "build": "bun build src/index.ts --outdir=dist --target=bun --format=esm --packages=external",
    "test": "bun test ./tests",
    "test:providers": "bun ./tests/providers.ts",
    "typecheck": "bun tsc --noEmit",
    "prepublishOnly": "bun run build"
  },
  "devDependencies": {
    "@types/bun": "latest"
  },
  "peerDependencies": {
    "typescript": "^5.9.3"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.14.46",
    "@opencode-ai/sdk": "^1.14.46",
    "zod": "^4.4.3"
  }
}
